   "morning_observation": "Tuesday, February 2, 2016. The local radio plays three bright notes and announces a groundhog forecast in the town square. A delivery van backfires twice.",
   "episodes_in_order": [
    "6:00 am in inn: Ellis reaches the square. June says: Morning, Ellis. Let's get this show on the air. June spends the period at the inn. You see Cal at the square.",
    "9:30 am in square: Ellis spends the period at the square. Cal says: I'll hold tight here until the band is ready to play. Cal spends the period at the square.",
    "1:00 pm in square: Ellis uses the paid ticket and rides the coach all the way to Pittsburgh. Cal says: Got the cornet player. Battery's dead. Tell me what you need next, Ellis. Cal uses the camera's last charged take to film the cornet player."
   ]
  },
  {
   "most_recent_own_plan": "Catch the 1:00 pm coach to return to Pittsburgh."
  }
 ],
 "available_actions": {
  "spend_time_here": "Stay where you are for the period.",
  "look_around": "Inspect your present surroundings.",
  "call_sister": "Telephone your sister in Pittsburgh about tomorrow's move.",
